html:
{{ print_control(doc) }}
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro money(value) -%}{{ "{:,.0f}".format(value | float) if value else "0" }}{%- endmacro -%}
{%- macro score(value) -%}{{ "{:.1f}".format(value | float) if value else "" }}{%- endmacro -%}
<style>
.hpb { font-size: 11.5px; color: #1A1A1A; }
.hpb h2 { font-size: 16px; margin: 0 0 2px; color: #0A2540; }
.hpb h3 { font-size: 12.5px; margin: 14px 0 6px; padding-bottom: 3px; border-bottom: 1px solid #0A2540; color: #0A2540;
  text-transform: uppercase; letter-spacing: .03em; }
.hpb .hpb-sub { color: #5B6B7F; margin-bottom: 8px; }
.hpb .hpb-grid { width: 100%; border-collapse: collapse; }
.hpb .hpb-grid th { text-align: left; font-weight: 600; border-bottom: 1px solid #C3D0E0; padding: 3px 4px; }
.hpb .hpb-grid td { border-bottom: 1px solid #EDF1F7; padding: 3px 4px; vertical-align: top; }
.hpb .hpb-num { text-align: right; }
.hpb ul { margin: 0; padding-left: 16px; }
</style>
<div class="hpb">
<h2>{{ _("HR Partner Brief") }} {{ v(doc.week) }}</h2>
<div class="hpb-sub">{{ v(doc.branch or _("All Plants")) }} &middot; {{ frappe.utils.format_date(doc.week_start) }}
 {{ _("to") }} {{ frappe.utils.format_date(doc.week_end) }} &middot; {{ _("Plant score") }} {{ score(doc.plant_score) }}
 ({{ v(doc.plant_status) }})</div>
<div>{{ v(doc.verdict) }}</div>

<h3>{{ _("The Business Case") }}</h3>
<table class="hpb-grid">
<tr><td>{{ _("Waste and rejects") }}</td><td class="hpb-num">{{ money(doc.waste_value) }}</td>
<td>{{ _("Person-shifts without full PPE") }}</td><td class="hpb-num">{{ doc.not_wearing or 0 }}</td></tr>
<tr><td>{{ _("Customer complaints") }}</td><td class="hpb-num">{{ money(doc.complaint_value) }}</td>
<td>{{ _("Person-shifts absent") }}</td><td class="hpb-num">{{ doc.absent or 0 }}</td></tr>
<tr><td><b>{{ _("Money lost") }}</b></td><td class="hpb-num"><b>{{ money(doc.money_lost) }}</b></td>
<td>{{ _("Machine hours lost") }}</td><td class="hpb-num">{{ "{:,.1f}".format(doc.hours_lost or 0) }}</td></tr>
<tr><td>{{ _("Sections over a limit") }}</td><td class="hpb-num">{{ doc.over_limit or 0 }}</td>
<td>{{ _("Safety incidents") }}</td><td class="hpb-num">{{ doc.safety_incidents or 0 }}</td></tr>
</table>

<h3>{{ _("Where the Money Went") }}</h3>
<table class="hpb-grid">
<tr><th>{{ _("Section") }}</th><th class="hpb-num">{{ _("Waste") }}</th><th class="hpb-num">{{ _("Complaints") }}</th>
<th class="hpb-num">{{ _("Score") }}</th><th>{{ _("Status") }}</th><th>{{ _("Weakest Area") }}</th></tr>
{%- for row in doc.top_sections %}
<tr><td>{{ v(row.work_section) }}</td><td class="hpb-num">{{ money(row.waste_value) }}</td>
<td class="hpb-num">{{ money(row.complaint_value) }}</td><td class="hpb-num">{{ score(row.score) }}</td>
<td>{{ v(row.status) }}</td><td>{{ v(row.weakest_area) }}</td></tr>
{%- endfor %}
</table>

<h3>{{ _("Supervisors to Coach") }}</h3>
<table class="hpb-grid">
<tr><th>{{ _("Supervisor") }}</th><th>{{ _("Section") }}</th><th>{{ _("Shift") }}</th><th class="hpb-num">{{ _("Score") }}</th>
<th>{{ _("Weakest Area") }}</th><th>{{ _("Agreed HR Action") }}</th></tr>
{%- for row in doc.supervisors %}
<tr><td>{{ v(row.supervisor_name or row.supervisor) }}</td><td>{{ v(row.work_section) }}</td><td>{{ v(row.shift) }}</td>
<td class="hpb-num">{{ score(row.score) }}</td><td>{{ v(row.weakest_area) }}</td><td>{{ v(row.action) }}</td></tr>
{%- endfor %}
</table>

<h3>{{ _("Accountability") }}</h3>
<div>{{ _("Interventions open") }}: {{ doc.open_interventions or 0 }} &middot; {{ _("overdue") }}:
 {{ doc.overdue_interventions or 0 }} &middot; {{ _("raised this week") }}: {{ doc.raised_interventions or 0 }}</div>

<h3>{{ _("Talking Points") }}</h3>
<ul>
{%- for line in (doc.talking_points or "").split("\n") if line.strip() %}
<li>{{ v(line) }}</li>
{%- endfor %}
</ul>

<h3>{{ _("Workforce Signals") }}</h3>
{%- if doc.signals %}
<table class="hpb-grid">
<tr><th>{{ _("Section") }}</th><th class="hpb-num">{{ _("Signals") }}</th><th>{{ _("HR Alert") }}</th></tr>
{%- for row in doc.signals %}
<tr><td>{{ v(row.work_section) }}</td><td class="hpb-num">{{ row.signals or 0 }}</td><td>{{ v(row.alert) }}</td></tr>
{%- endfor %}
</table>
{%- else %}
<div>{{ _("No section shows two or more workforce signals together this week.") }}</div>
{%- endif %}

<h3>{{ _("Questions for the Plant Manager") }}</h3>
<table class="hpb-grid">
{%- for row in doc.questions %}
<tr><td style="width:38%">{{ loop.index }}. {{ v(row.question) }}</td><td>{{ v(row.answer) }}</td></tr>
{%- endfor %}
</table>
{%- if doc.notes %}
<h3>{{ _("HR Notes") }}</h3>
<div>{{ doc.notes }}</div>
{%- endif %}
</div>
